        assertThat(result.body().get("operation").asText()).isEqualTo("SPLIT");
        assertThat(result.body().get("segments")).hasSize(2);

        // 旧段废止、新段当前且位置连续
        assertThat(jdbc.queryForObject(
                "SELECT status FROM segment WHERE document_id=? AND segment_id='s1'",
