        // REFERENCE 候选：按映射直接拼接（此处每新段仅一片），片段边界正确
        JsonNode references = result.body().get("references");
        assertThat(references).hasSize(4);
        JsonNode n1En = references.get(0);
        assertThat(n1En.get("segmentId").asText()).isEqualTo("n1");
