                    + "{\"newSegmentId\":\"n2\",\"language\":\"en\","
                    + "\"fragments\":[{\"segmentId\":\"s1\",\"translationVersion\":1}]}]");
    ApiResult retry = structureChange(docId, fixed);
    assertThat(retry.status()).isEqualTo(201);
}

